export function parseDuration(s) {
  const str = String(s).trim();
  const units = { s: 1, m: 60, h: 3600, d: 86400 };
  let total = 0, matched = false, end = 0;
  for (const m of str.matchAll(/(\d+)([dhms])/g)) {
    total += Number(m[1]) * units[m[2]];
    matched = true;
    end = m.index + m[0].length;
  }
  if (!matched || end !== str.length) throw new Error("invalid duration");
  return total;
}

